const input = $input.first().json;

let outfit =
  input.outfit ??
  input.output ??
  input.response ??
  input.content ??
  input;

if (outfit?.content?.parts?.[0]?.text) {
  outfit = outfit.content.parts[0].text;
}

if (outfit?.parts?.[0]?.text) {
  outfit = outfit.parts[0].text;
}

if (outfit?.text) {
  outfit = outfit.text;
}

if (typeof outfit === "string") {
  const cleaned = outfit
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  try {
    outfit = JSON.parse(cleaned);
  } catch {
    throw new Error(
      `Gemini returned invalid JSON: ${cleaned}`
    );
  }
}

if (
  !outfit?.title ||
  !Array.isArray(outfit?.item_ids)
) {
  throw new Error(
    `Gemini response is missing title or item_ids: ${JSON.stringify(
      outfit
    )}`
  );
}

return [
  {
    json: {
      success: true,
      outfit: {
        title: String(outfit.title),
        item_ids: outfit.item_ids,
        reason: String(
          outfit.reason ?? ""
        ),
        styling_tip: String(
          outfit.styling_tip ?? ""
        ),
        confidence: Number(
          outfit.confidence ?? 0
        ),
        preferences_applied:
          Array.isArray(
            outfit.preferences_applied
          )
            ? outfit.preferences_applied
            : [],
      },
    },
  },
];
